from pathlib import Path
import zlib,base64
p=Path('index.html')
s=p.read_text(encoding='utf-8')
if 'let draftColazione = {};' not in s:
    s=s.replace('let draftPasto = {};','let draftPasto = {};\nlet draftColazione = {};',1)
enc=''
block=zlib.decompress(base64.b64decode(enc)).decode('utf-8')
start=s.index('async function renderColazione(giorno, elementId){')
end=s.index('\nasync function apriModalDettaglioColazione',start)
s=s[:start]+block+s[end:]
p.write_text(s,encoding='utf-8')
print('v12 breakfast patch applied')